function validate([days, meetings]) {
  if (!Number.isInteger(days) || days < 1 || days > 1000000000) return 'days is between 1 and 10^9.';
  if (!Array.isArray(meetings) || meetings.length < 1 || meetings.length > 100000) return 'meetings needs 1 to 10^5 entries.';
  for (const m of meetings) {
    if (!Array.isArray(m) || m.length !== 2) return 'Each meeting is a pair [start, end].';
    if (!Number.isInteger(m[0]) || !Number.isInteger(m[1])) return 'Meeting days are whole numbers.';
    if (m[0] < 1 || m[0] > m[1] || m[1] > days) return 'Each meeting needs 1 <= start <= end <= days.';
  }
  return null;
}

