function countDays(days, meetings) {
  meetings.sort((a, b) => a[0] - b[0]);
  let free = 0;
  let lastEnd = 0;

  for (const [start, end] of meetings) {
    if (start > lastEnd + 1) {
      free += start - lastEnd - 1;
    }
    lastEnd = Math.max(lastEnd, end);
  }

  free += days - lastEnd;
  return free;
}

