function countDays(days, meetings) {
  // Cut the day line at every place where coverage can change, then test each piece separately.
  const cuts = new Set([1, days + 1]);
  for (const [s, e] of meetings) { cuts.add(s); cuts.add(e + 1); }
  const points = [...cuts].sort((a, b) => a - b);
  let count = 0;
  for (let k = 0; k + 1 < points.length; k++) {
    const p = points[k], q = points[k + 1];
    if (p < 1 || p > days) continue;
    let covered = false;
    for (const [s, e] of meetings) if (s <= p && p <= e) covered = true;
    if (!covered) count += q - p;
  }
  return count;
}

