function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const days = pick(1, 15);
    const n = pick(1, 6);
    const meetings = [];
    for (let i = 0; i < n; i++) {
      const start = pick(1, days);
      const end = rand() < 0.4 ? start : pick(start, Math.min(days, start + pick(0, 6)));
      meetings.push([start, end]);
    }
    return [days, meetings];
  }
  const days = rand() < 0.5 ? 1000000000 : pick(2000, 20000);
  const n = 2000;
  const maxLength = Math.max(1, Math.floor(days / (n * (rand() < 0.5 ? 2 : 1))));
  const meetings = [];
  for (let i = 0; i < n; i++) {
    const start = pick(1, days);
    const end = Math.min(days, start + pick(0, maxLength));
    meetings.push([start, end]);
  }
  return [days, meetings];
}
